const docContentData = {
    "zh": {
        "sections": [
            {
                "id": "intro",
                "icon": "fa-rocket",
                "title": "卷轴系统理念与快速起步",
                "description": "轻量级、免侵入、全核心通用、绝对不崩服的控制台自动化系统",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    <strong>卷轴 (Scroll)</strong> 是 MC Web Panel 独创的免侵入自动化脚本系统。与传统的 Minecraft 服务端插件或模组（Bukkit/Spigot/Paper 插件、Forge/Fabric 模组）完全不同，卷轴运行在面板独立的 Node.js 事件循环与沙盒环境中，<strong>不需要在游戏服务端中安装任何前置 Mod 或 Loader</strong>。\n</p>\n\n<div class=\"row g-3 mb-4\">\n    <div class=\"col-md-4\">\n        <div class=\"card h-100 border-0 p-3 rounded-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n            <div class=\"d-flex align-items-center gap-2 mb-2 text-primary fw-bold\">\n                <i class=\"fa-solid fa-infinity\"></i>\n                <span>全核心全版本通用</span>\n            </div>\n            <p class=\"text-muted small mb-0 lh-base\">\n                纯净官方核心 (Vanilla)、Fabric、Forge、NeoForge、Paper、Purpur 乃至基岩版全版本兼容，彻底摆脱游戏大版本更新导致插件失效的困扰。\n            </p>\n        </div>\n    </div>\n    <div class=\"col-md-4\">\n        <div class=\"card h-100 border-0 p-3 rounded-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n            <div class=\"d-flex align-items-center gap-2 mb-2 text-success fw-bold\">\n                <i class=\"fa-solid fa-shield-halved\"></i>\n                <span>绝对隔离 · 永不崩服</span>\n            </div>\n            <p class=\"text-muted small mb-0 lh-base\">\n                卷轴代码运行在面板宿主进程中，即使脚本发生未捕获异常，也只会被沙盒安全隔离，绝不可能导致 Minecraft 服务端崩溃或损坏游戏存档。\n            </p>\n        </div>\n    </div>\n    <div class=\"col-md-4\">\n        <div class=\"card h-100 border-0 p-3 rounded-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n            <div class=\"d-flex align-items-center gap-2 mb-2 text-warning fw-bold\">\n                <i class=\"fa-solid fa-bolt\"></i>\n                <span>零停机 · 毫秒级热生效</span>\n            </div>\n            <p class=\"text-muted small mb-0 lh-base\">\n                支持在面板中在线修改代码或配置，保存后毫秒级热重载，无需重启服务器，随时随地敏捷调试与发布自动化交互规则。\n            </p>\n        </div>\n    </div>\n</div>\n\n<h5 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-folder-tree me-2 text-purple\"></i>极简目录结构</h5>\n<div class=\"row g-4 mb-4\">\n    <div class=\"col-md-6\">\n        <div class=\"code-block-wrapper shadow-sm rounded-4 overflow-hidden border\">\n            <div class=\"code-header d-flex justify-content-between px-3 py-2 small bg-dark bg-opacity-10 border-bottom\">\n                <span class=\"fw-bold\">目录树结构</span>\n                <span class=\"text-muted opacity-50\">Tree</span>\n            </div>\n            <pre class=\"p-3 small mb-0 dev-code-block\" style=\"background: var(--c-surface-elevated); overflow-x: auto; white-space: pre;\"><code>instances/<instanceId>/scrolls/my-scroll/\n├── scroll.json        # 卷轴清单元数据与配置规范 (必须)\n├── index.js           # 卷轴执行逻辑入口 (必须)\n└── config.json        # 卷轴个性化参数 (面板可视化配置)</code></pre>\n        </div>\n    </div>\n    <div class=\"col-md-6\">\n        <div class=\"code-block-wrapper shadow-sm rounded-4 overflow-hidden border\">\n            <div class=\"code-header d-flex justify-content-between px-3 py-2 small bg-dark bg-opacity-10 border-bottom\">\n                <span class=\"fw-bold\">快速起步模板</span>\n                <span class=\"text-muted opacity-50\">index.js</span>\n            </div>\n            <pre class=\"p-3 small mb-0 dev-code-block\" style=\"background: var(--c-surface-elevated); overflow-x: auto; white-space: pre;\"><code>module.exports = async function(scroll) {\n    // 监听玩家加入游戏\n    scroll.onPlayerJoin(async ({ player }) => {\n        scroll.sendTitle(player, {\n            title: \"欢迎进入世界\",\n            subtitle: \"享受精彩的冒险之旅！\",\n            color: \"gold\"\n        });\n        scroll.broadcast(\"§a欢迎玩家 §e\" + player + \" §a加入了服务器！\");\n    });\n\n    return {\n        destroy: async () => {\n            scroll.logger.info(\"卷轴注销清理完成\");\n        }\n    };\n};</code></pre>\n        </div>\n    </div>\n</div>\n"
            },
            {
                "id": "manifest",
                "icon": "fa-file-code",
                "title": "scroll.json 清单与可视化配置规范",
                "description": "元数据声明与 configSchema 动态配置表单生成机制",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    <code>scroll.json</code> 是卷轴的元数据清单文件，必须放置在卷轴的根目录下。系统不仅通过此文件识别卷轴名称与作者，还会依据 <code>configSchema</code> 自动在前端「卷轴工坊」中生成可视化的配置表单，让服主无需接触代码即可调整各项参数。\n</p>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-3 small text-uppercase text-secondary tracking-wider\">清单顶级字段说明</h6>\n        <div class=\"table-responsive\">\n            <table class=\"table table-sm dev-table mb-0 small text-muted\">\n                <thead>\n                    <tr class=\"border-bottom\">\n                        <th>字段名</th>\n                        <th>类型</th>\n                        <th>必填</th>\n                        <th>默认值</th>\n                        <th>说明</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td class=\"text-purple font-monospace py-2\">id</td><td>string</td><td class=\"text-danger\">是</td><td>—</td><td>卷轴唯一标识符，建议只包含小写字母、数字和中划线（如 <code>auto-cleaner</code>）。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">name</td><td>string | object</td><td class=\"text-danger\">是</td><td>—</td><td>显示名称。支持纯文本或中英多语言对象：<code>{ \"zh\": \"扫地姬\", \"en\": \"Auto Cleaner\" }</code>。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">version</td><td>string</td><td class=\"text-danger\">是</td><td>\"1.0.0\"</td><td>语义化版本号，如 <code>1.2.0</code>。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">author</td><td>string</td><td>否</td><td>—</td><td>作者或开发团队名称。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">description</td><td>string | object</td><td>否</td><td>—</td><td>功能介绍描述。支持纯文本或中英多语言对象。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">category</td><td>string</td><td>否</td><td>\"tools\"</td><td>分类归属，可选值：<code>tools</code>（系统工具）、<code>interactive</code>（玩家互动）、<code>utility</code>（实用辅助）。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">icon</td><td>string</td><td>否</td><td>\"fa-scroll\"</td><td>FontAwesome 6 图标类名（如 <code>fa-broom</code>, <code>fa-bed</code>, <code>fa-shield</code>）。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">color</td><td>string</td><td>否</td><td>\"#8b5cf6\"</td><td>卷轴在前端卡片的主题色 HEX 或 CSS 颜色值。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">main</td><td>string</td><td>否</td><td>\"index.js\"</td><td>执行逻辑入口文件相对路径。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">defaultEnabled</td><td>boolean</td><td>否</td><td>true</td><td>初次导入时是否默认启用。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">configSchema</td><td>object | array</td><td>否</td><td>{}</td><td>可视化配置表单规范，详见下方。</td></tr>\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n\n<h5 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-sliders me-2 text-purple\"></i>configSchema 动态表单规格</h5>\n<p class=\"text-muted mb-3 small\">\n    支持对象字典定义或数组定义。系统支持四种基础控件类型：<code>string</code>（单行文本框）、<code>number</code>（数值微调框）、<code>boolean</code>（开关切换）、<code>select</code>（下拉选择框）。服主在面板保存的配置会即时注入到 <code>scroll.config</code> 中。\n</p>\n\n<div class=\"code-block-wrapper shadow-sm rounded-4 overflow-hidden border mb-4\">\n    <div class=\"code-header d-flex justify-content-between px-3 py-2 small bg-dark bg-opacity-10 border-bottom\">\n        <span class=\"fw-bold\">scroll.json 完整清单范例</span>\n        <span class=\"text-muted opacity-50\">JSON</span>\n    </div>\n    <pre class=\"p-3 small mb-0 dev-code-block\" style=\"background: var(--c-surface-elevated); overflow-x: auto; white-space: pre;\"><code>{\n    \"id\": \"welcome-scroll\",\n    \"name\": {\n        \"zh\": \"新手迎宾大标题\",\n        \"en\": \"Welcome Title\"\n    },\n    \"version\": \"1.0.0\",\n    \"author\": \"4YStudio\",\n    \"description\": {\n        \"zh\": \"玩家进入服务器时在屏幕中央展示金色 Title 大标题并发送欢迎广播。\",\n        \"en\": \"Shows a golden welcome title and broadcast message upon player join.\"\n    },\n    \"icon\": \"fa-bullhorn\",\n    \"color\": \"#f59e0b\",\n    \"category\": \"interactive\",\n    \"main\": \"index.js\",\n    \"defaultEnabled\": true,\n    \"configSchema\": {\n        \"welcomeMessage\": {\n            \"type\": \"string\",\n            \"title\": \"全服聊天欢迎词\",\n            \"default\": \"§a热烈欢迎新伙伴 §e{player} §a进入了服务器！\",\n            \"description\": \"支持 § 颜色代码，{player} 会自动替换为进服玩家名\"\n        },\n        \"titleText\": {\n            \"type\": \"string\",\n            \"title\": \"主标题文字\",\n            \"default\": \"欢迎光临\",\n            \"description\": \"全屏大标题主文本\"\n        },\n        \"titleColor\": {\n            \"type\": \"select\",\n            \"title\": \"主标题颜色\",\n            \"default\": \"gold\",\n            \"options\": [\n                { \"label\": \"金色 (Gold)\", \"value\": \"gold\" },\n                { \"label\": \"绿色 (Green)\", \"value\": \"green\" },\n                { \"label\": \"水青色 (Aqua)\", \"value\": \"aqua\" },\n                { \"label\": \"粉紫色 (Light Purple)\", \"value\": \"light_purple\" }\n            ]\n        },\n        \"countdownSec\": {\n            \"type\": \"number\",\n            \"title\": \"延时秒数\",\n            \"default\": 3,\n            \"min\": 1,\n            \"max\": 30\n        },\n        \"enableSound\": {\n            \"type\": \"boolean\",\n            \"title\": \"启用提示音效\",\n            \"default\": true\n        }\n    }\n}</code></pre>\n</div>\n"
            },
            {
                "id": "lifecycle",
                "icon": "fa-arrows-spin",
                "title": "生命周期与沙盒执行规范",
                "description": "模块导出契约、热重载流程与资源清理策略",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    卷轴的入口文件（默认为 <code>index.js</code>）必须导出一个 <code>async</code> 函数。当卷轴被加载或启用时，该函数会被调用，系统将向其注入唯一的 <strong>卷轴上下文对象 (scroll context)</strong>。\n</p>\n\n<div class=\"code-block-wrapper shadow-sm rounded-4 overflow-hidden border mb-4\">\n    <div class=\"code-header d-flex justify-content-between px-3 py-2 small bg-dark bg-opacity-10 border-bottom\">\n        <span class=\"fw-bold\">入口函数与销毁契约</span>\n        <span class=\"text-muted opacity-50\">Javascript</span>\n    </div>\n    <pre class=\"p-3 small mb-0 dev-code-block\" style=\"background: var(--c-surface-elevated); overflow-x: auto; white-space: pre;\"><code>/**\n * 卷轴入口函数\n * @param {Object} scroll - 卷轴上下文对象，注入全套 DSL 与环境接口\n */\nmodule.exports = async function(scroll) {\n    scroll.logger.info(\"卷轴正在初始化...\");\n\n    // 1. 初始化业务逻辑、注册监听器或定时任务\n    const timer = setInterval(() => {\n        // 自定义定时逻辑\n    }, 60000);\n\n    // 2. 返回包含 destroy 钩子的对象 (推荐)\n    return {\n        destroy: async () => {\n            clearInterval(timer); // 主动清理定时器\n            scroll.logger.info(\"卷轴已被注销并完成清理\");\n        }\n    };\n};</code></pre>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold text-warning mb-3\"><i class=\"fa-solid fa-triangle-exclamation me-2\"></i>定时器与资源防泄漏规范</h6>\n        <ul class=\"text-muted small mb-0 ps-3 lh-lg\">\n            <li><strong>优先使用 <code>scroll.schedule(intervalMs, fn)</code></strong>：引擎会在卷轴被禁用、重载或卸载时，<strong>全自动清理</strong>所有通过 <code>scroll.schedule</code> 注册的定时器，无需手动维护引用。</li>\n            <li><strong>原生 <code>setInterval</code> / <code>setTimeout</code></strong>：如果使用了 Node 原生定时器，必须在导出的 <code>destroy()</code> 钩子中执行 <code>clearInterval</code> / <code>clearTimeout</code>，避免重复产生幽灵定时任务。</li>\n            <li><strong>沙盒错误隔离</strong>：事件监听器内部的异常均被 <code>try-catch</code> 封装，即使你的代码出现运行时 TypeError，也不会导致面板崩溃或终止其他卷轴的执行。</li>\n        </ul>\n    </div>\n</div>\n"
            },
            {
                "id": "listeners",
                "icon": "fa-ear-listen",
                "title": "事件监听器 API 参考",
                "description": "监听玩家进出服、聊天指令拦截、阵亡与控制台日志",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    卷轴通过控制台数据流和原生事件驱动，无需任何侵入式客户端或服务端补丁即可捕获 Minecraft 服务器内部的关键事件：\n</p>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.onPlayerJoin(callback)</h6>\n        <p class=\"small text-muted mb-2\">当玩家加入游戏世界并完成握手连接时触发。</p>\n        <div class=\"table-responsive mb-3\">\n            <table class=\"table table-sm dev-table mb-0 small text-muted\">\n                <thead><tr class=\"border-bottom\"><th>参数属性</th><th>类型</th><th>说明</th></tr></thead>\n                <tbody>\n                    <tr><td class=\"font-monospace text-purple\">payload.player</td><td>string</td><td>加入服务器的玩家游戏 ID（如 <code>\"Alex\"</code>）。</td></tr>\n                    <tr><td class=\"font-monospace text-purple\">payload.raw</td><td>string</td><td>底层触发该事件的完整控制台原始日志行。</td></tr>\n                </tbody>\n            </table>\n        </div>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>scroll.onPlayerJoin(async ({ player }) => {\n    scroll.logger.info(\"玩家加入游戏: \" + player);\n    scroll.sendCommand(\"effect give \" + player + \" minecraft:speed 10 1 true\");\n});</code></pre>\n    </div>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.onPlayerQuit(callback)</h6>\n        <p class=\"small text-muted mb-2\">当玩家退出游戏世界或断开连接时触发。</p>\n        <div class=\"table-responsive mb-3\">\n            <table class=\"table table-sm dev-table mb-0 small text-muted\">\n                <thead><tr class=\"border-bottom\"><th>参数属性</th><th>类型</th><th>说明</th></tr></thead>\n                <tbody>\n                    <tr><td class=\"font-monospace text-purple\">payload.player</td><td>string</td><td>断开连接的玩家游戏 ID。</td></tr>\n                    <tr><td class=\"font-monospace text-purple\">payload.raw</td><td>string</td><td>控制台原始日志行。</td></tr>\n                </tbody>\n            </table>\n        </div>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>scroll.onPlayerQuit(async ({ player }) => {\n    scroll.broadcast(\"§7[提示] 玩家 \" + player + \" 悄悄离开了世界。\");\n});</code></pre>\n    </div>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.onChat(callback)</h6>\n        <p class=\"small text-muted mb-2\">捕获玩家在游戏公共聊天栏中的所有发言。<strong>是编写自定义控制台聊天指令（例如 <code>!spawn</code>、<code>!tpa</code>、<code>!help</code>）的核心利器！</strong></p>\n        <div class=\"table-responsive mb-3\">\n            <table class=\"table table-sm dev-table mb-0 small text-muted\">\n                <thead><tr class=\"border-bottom\"><th>参数属性</th><th>类型</th><th>说明</th></tr></thead>\n                <tbody>\n                    <tr><td class=\"font-monospace text-purple\">payload.player</td><td>string</td><td>发言玩家名称。</td></tr>\n                    <tr><td class=\"font-monospace text-purple\">payload.message</td><td>string</td><td>玩家发送的文本内容（已自动去除首尾空格）。</td></tr>\n                    <tr><td class=\"font-monospace text-purple\">payload.raw</td><td>string</td><td>控制台原始日志。</td></tr>\n                </tbody>\n            </table>\n        </div>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>scroll.onChat(async ({ player, message }) => {\n    // 监听聊天自定义指令\n    if (message === \"!spawn\" || message === \"！回城\") {\n        scroll.broadcast(\"§a[传送] 正在将玩家 §e\" + player + \" §a送回世界出生点...\");\n        scroll.sendCommand(\"tp \" + player + \" 0 80 0\");\n    }\n});</code></pre>\n    </div>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.onDeath(callback)</h6>\n        <p class=\"small text-muted mb-2\">捕获玩家阵亡事件及阵亡原因。</p>\n        <div class=\"table-responsive mb-3\">\n            <table class=\"table table-sm dev-table mb-0 small text-muted\">\n                <thead><tr class=\"border-bottom\"><th>参数属性</th><th>类型</th><th>说明</th></tr></thead>\n                <tbody>\n                    <tr><td class=\"font-monospace text-purple\">payload.player</td><td>string</td><td>阵亡玩家的 ID。</td></tr>\n                    <tr><td class=\"font-monospace text-purple\">payload.deathReason</td><td>string</td><td>阵亡讣告描述（如 <code>\"was slain by Zombie\"</code> 或 <code>\"fell from a high place\"</code>）。</td></tr>\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.onLog(callback)</h6>\n        <p class=\"small text-muted mb-2\">捕获服务端输出的每一行原始控制台文本。通过编写正则表达式，可以实现对任意 Mod 或插件输出的深度监听。</p>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>scroll.onLog(async ({ raw }) => {\n    // 捕获特定事件特征\n    if (raw.includes(\"Advancement Done\")) {\n        scroll.logger.info(\"玩家达成成就: \" + raw);\n    }\n});</code></pre>\n    </div>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.schedule(intervalMs, callback)</h6>\n        <p class=\"small text-muted mb-2\">注册生命周期绑定的安全定时调度器。卷轴注销或禁用时，系统自动安全回收，防止内存泄漏。</p>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>// 每 10 分钟自动执行一次存档保存\nscroll.schedule(10 * 60 * 1000, async () => {\n    scroll.sendCommand(\"save-all\");\n    scroll.logger.info(\"自动执行 save-all 完成\");\n});</code></pre>\n    </div>\n</div>\n"
            },
            {
                "id": "dsl_api",
                "icon": "fa-wand-magic-sparkles",
                "title": "DSL 上下文工具 API 参考",
                "description": "操作指令注入、全屏大标题、ActionBar、数据存取全套函数",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    系统向卷轴入口函数注入的 <code>scroll</code> 对象封装了一系列高抽象度、开箱即用的实用 DSL 工具：\n</p>\n\n<div class=\"table-responsive mb-4\">\n    <table class=\"table table-sm dev-table mb-0 small text-muted\">\n        <thead>\n            <tr class=\"border-bottom\">\n                <th>方法 / 属性</th>\n                <th>签名 / 类型</th>\n                <th>说明</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.sendCommand(cmd)</td>\n                <td><code>(cmd: string) => void</code></td>\n                <td>向当前活跃 Minecraft 服务器的控制台标准输入 (stdin) 发送命令。无需加斜杠前缀 <code>/</code>。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.sendTitle(player, opts)</td>\n                <td><code>(player: string, opts: Object) => void</code></td>\n                <td>向指定玩家（或 <code>@a</code> 全体玩家）屏幕正中央发送标题。支持 <code>title</code>、<code>subtitle</code>、<code>color</code>、<code>fadeIn</code>、<code>stay</code>、<code>fadeOut</code>。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.sendActionBar(player, text)</td>\n                <td><code>(player: string, text: string) => void</code></td>\n                <td>向指定玩家发送屏幕底部快捷栏通知（ActionBar），不遮挡视野，支持颜色代码。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.broadcast(text)</td>\n                <td><code>(text: string) => void</code></td>\n                <td>向全服聊天框广播一条格式化消息。内置安全转义，支持 <code>§</code> 颜色代码。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.storage</td>\n                <td><code>ScrollStorage</code></td>\n                <td>内置持久化键值对存储数据库，数据安全保存至本地 <code>data/storage.json</code>。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.config</td>\n                <td><code>Object</code></td>\n                <td>只读对象。实时包含服主在前端界面为该卷轴配置的键值参数。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.logger</td>\n                <td><code>{ info, warn, error }</code></td>\n                <td>标准化日志记录器，输出自动带有 <code>[Scroll:ID]</code> 前缀。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.sleep(ms)</td>\n                <td><code>(ms: number) => Promise&lt;void&gt;</code></td>\n                <td>异步休眠等待工具函数，用法：<code>await scroll.sleep(1000)</code>。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.instancesDir</td>\n                <td><code>string</code></td>\n                <td>服务器实例存储根目录的绝对物理路径。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.instanceId</td>\n                <td><code>string</code></td>\n                <td>当前所绑定的实例 ID（如 <code>default</code>）。</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h5 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-database me-2 text-purple\"></i>scroll.storage 持久化存储详解</h5>\n<div class=\"code-block-wrapper shadow-sm rounded-4 overflow-hidden border mb-4\">\n    <div class=\"code-header d-flex justify-content-between px-3 py-2 small bg-dark bg-opacity-10 border-bottom\">\n        <span class=\"fw-bold\">Storage 使用范例</span>\n        <span class=\"text-muted opacity-50\">Javascript</span>\n    </div>\n    <pre class=\"p-3 small mb-0 dev-code-block\" style=\"background: var(--c-surface-elevated); overflow-x: auto; white-space: pre;\"><code>// 读取键值（提供默认值）\nconst points = scroll.storage.get(\"player_points_\" + player, 0);\n\n// 设置键值（自动写入 data/storage.json）\nscroll.storage.set(\"player_points_\" + player, points + 10);\n\n// 判断是否存在某键\nif (scroll.storage.has(\"last_checkin_time\")) { ... }\n\n// 删除键\nscroll.storage.delete(\"temp_token\");\n\n// 获取全部键值对象\nconst allData = scroll.storage.getAll();</code></pre>\n</div>\n"
            },
            {
                "id": "minecraft_commands",
                "icon": "fa-terminal",
                "title": "Minecraft 原版指令与 Tellraw/Title 格式指南",
                "description": "色彩代码、JSON Text 规范与跨版本兼容技巧",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    在编写卷轴交互时，合理使用原版 <code>/tellraw</code> 和 <code>/title</code> 命令可以呈现极其绚丽的 UI 效果：\n</p>\n\n<div class=\"row g-4 mb-4\">\n    <div class=\"col-md-6\">\n        <div class=\"card h-100 border-0 p-3 rounded-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n            <h6 class=\"fw-bold text-primary mb-3\">经典 § 颜色代码对照</h6>\n            <div class=\"row g-2 small font-monospace\">\n                <div class=\"col-6\"><span style=\"color:#000000;background:#fff;padding:2px 4px;border-radius:4px;\">§0 黑色</span></div>\n                <div class=\"col-6\"><span style=\"color:#0000aa;\">§1 深蓝</span></div>\n                <div class=\"col-6\"><span style=\"color:#00aa00;\">§2 深绿</span></div>\n                <div class=\"col-6\"><span style=\"color:#00aaaa;\">§3 湖蓝</span></div>\n                <div class=\"col-6\"><span style=\"color:#aa0000;\">§4 深红</span></div>\n                <div class=\"col-6\"><span style=\"color:#aa00aa;\">§5 紫色</span></div>\n                <div class=\"col-6\"><span style=\"color:#ffaa00;\">§6 金黄</span></div>\n                <div class=\"col-6\"><span style=\"color:#aaaaaa;\">§7 灰色</span></div>\n                <div class=\"col-6\"><span style=\"color:#555555;\">§8 深灰</span></div>\n                <div class=\"col-6\"><span style=\"color:#5555ff;\">§9 亮蓝</span></div>\n                <div class=\"col-6\"><span style=\"color:#55ff55;\">§a 亮绿</span></div>\n                <div class=\"col-6\"><span style=\"color:#55ffff;\">§b 天蓝</span></div>\n                <div class=\"col-6\"><span style=\"color:#ff5555;\">§c 鲜红</span></div>\n                <div class=\"col-6\"><span style=\"color:#ff55ff;\">§d 粉红</span></div>\n                <div class=\"col-6\"><span style=\"color:#ffff55;\">§e 黄色</span></div>\n                <div class=\"col-6\"><span style=\"color:#ffffff;\">§f 白色</span></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"col-md-6\">\n        <div class=\"card h-100 border-0 p-3 rounded-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n            <h6 class=\"fw-bold text-success mb-3\">Minecraft 原版 JSON Text 规范</h6>\n            <p class=\"small text-muted mb-2\">使用 <code>/tellraw</code> 或 <code>/title</code> 时，文本对象遵循标准 JSON 格式：</p>\n            <pre class=\"p-2 small mb-0 rounded-3 border\" style=\"background: var(--c-surface); font-size: 0.75rem;\"><code>[\"\", {\"text\":\"[公告] \",\"color\":\"gold\",\"bold\":true}, {\"text\":\"欢迎访问官网！\",\"color\":\"yellow\",\"clickEvent\":{\"action\":\"open_url\",\"value\":\"https://example.com\"}}]</code></pre>\n        </div>\n    </div>\n</div>\n"
            },
            {
                "id": "examples",
                "icon": "fa-laptop-code",
                "title": "五大实战案例全套代码",
                "description": "从聊天回城指令到单人跳过黑夜，开箱即用的完整实战源码",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    以下提供了 5 个高频实用场景的完整卷轴代码，可直接复制到面板「在线工坊」或本地目录中使用：\n</p>\n\n<!-- 案例 1 -->\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <div class=\"d-flex align-items-center gap-2 mb-2\">\n            <span class=\"badge bg-primary rounded-pill px-2.5\">案例 1</span>\n            <h6 class=\"fw-bold m-0\">聊天快捷指令回城卷轴 (!spawn)</h6>\n        </div>\n        <p class=\"small text-muted mb-3\">玩家在聊天框输入 <code>!spawn</code>，卷轴检查 60 秒冷却时间，若冷却完毕则将其传送至世界出生点并扣除传送费用。</p>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>module.exports = async function(scroll) {\n    const cooldowns = new Map();\n\n    scroll.onChat(async ({ player, message }) => {\n        if (message.trim().toLowerCase() !== \"!spawn\" && message.trim() !== \"！回城\") return;\n\n        const now = Date.now();\n        const lastUsed = cooldowns.get(player) || 0;\n        const remaining = Math.ceil((60000 - (now - lastUsed)) / 1000);\n\n        if (remaining > 0) {\n            scroll.sendActionBar(player, \"§c冷却中！还需等待 \" + remaining + \" 秒后方可再次回城。\");\n            return;\n        }\n\n        cooldowns.set(player, now);\n        scroll.sendActionBar(player, \"§a正在传送回世界出生点...\");\n        scroll.sendCommand(\"tp \" + player + \" 0 80 0\");\n        scroll.sendCommand(\"effect give \" + player + \" minecraft:regeneration 5 1 true\");\n        scroll.broadcast(\"§6[传送] §e玩家 §b\" + player + \" §e已安全传送回城。\");\n    });\n\n    return {\n        destroy: async () => {\n            cooldowns.clear();\n        }\n    };\n};</code></pre>\n    </div>\n</div>\n\n<!-- 案例 2 -->\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <div class=\"d-flex align-items-center gap-2 mb-2\">\n            <span class=\"badge bg-success rounded-pill px-2.5\">案例 2</span>\n            <h6 class=\"fw-bold m-0\">违禁词自动检测与警告卷轴</h6>\n        </div>\n        <p class=\"small text-muted mb-3\">检测玩家聊天内容，包含敏感词时自动拦截并记录警告次数，达到 3 次自动执行临时禁言或踢出。</p>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>module.exports = async function(scroll) {\n    const BAD_WORDS = [\"炸服\", \"外挂\", \"刷物品\", \"骂人词\"];\n\n    scroll.onChat(async ({ player, message }) => {\n        const found = BAD_WORDS.some(word => message.includes(word));\n        if (!found) return;\n\n        const count = (scroll.storage.get(\"warn_\" + player, 0)) + 1;\n        scroll.storage.set(\"warn_\" + player, count);\n\n        scroll.broadcast(\"§c[巡查姬] §e玩家 §b\" + player + \" §e发表了违规言论！(累计警告: \" + count + \"/3)\");\n        scroll.sendTitle(player, {\n            title: \"§c言论违规警告\",\n            subtitle: \"请文明游戏，当前警告: \" + count + \"/3\",\n            color: \"red\"\n        });\n\n        if (count >= 3) {\n            scroll.sendCommand(\"kick \" + player + \" 您因多次违规发言已被移出服务器\");\n            scroll.storage.set(\"warn_\" + player, 0);\n        }\n    });\n};</code></pre>\n    </div>\n</div>\n\n<!-- 案例 3 -->\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <div class=\"d-flex align-items-center gap-2 mb-2\">\n            <span class=\"badge bg-warning text-dark rounded-pill px-2.5\">案例 3</span>\n            <h6 class=\"fw-bold m-0\">定时全服整点红包/幸运抽奖卷轴</h6>\n        </div>\n        <p class=\"small text-muted mb-3\">每隔 1 小时向全服在线玩家派发随机经验或物品奖励，活跃服务器气氛。</p>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>module.exports = async function(scroll) {\n    // 每 60 分钟执行一次\n    scroll.schedule(60 * 60 * 1000, async () => {\n        scroll.broadcast(\"§d[幸运天降] §e整点空投已抵达！全体在线玩家获得 5 级经验与金苹果奖励！\");\n        scroll.sendCommand(\"xp add @a 5 levels\");\n        scroll.sendCommand(\"give @a minecraft:golden_apple 1\");\n        scroll.sendCommand(\"playsound minecraft:ui.toast.challenge_complete master @a\");\n    });\n};</code></pre>\n    </div>\n</div>\n"
            },
            {
                "id": "publishing",
                "icon": "fa-cloud-arrow-up",
                "title": "打包与发布至 GitHub 卷轴商店",
                "description": "如何将自制卷轴打包并提交到官方在线商店",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    编写完成并自测通过的卷轴，可以非常方便地打包并提交给云语官方仓库，让全球的服主在面板中一键下载安装：\n</p>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-file-zipper me-2 text-purple\"></i>打包规范说明</h6>\n        <ol class=\"small text-muted ps-3 mb-0 lh-lg\">\n            <li><strong>根目录结构</strong>：进入你的卷轴目录，将 <code>scroll.json</code> 和 <code>index.js</code> 直接选中并打包为 ZIP 文件（注意：不要在 ZIP 内包含多余的一层同名文件夹）。</li>\n            <li><strong>文件名规范</strong>：ZIP 文件名必须严格与 <code>scroll.json</code> 中的 <code>id</code> 保持一致，例如 <code>my-scroll.zip</code>。</li>\n            <li><strong>自动构建索引</strong>：将打包好的 <code>my-scroll.zip</code> 放置于项目的 <code>docs/scrolls_shop/</code> 目录下，运行 <code>npm run build:scrolls-shop</code>，系统会自动解析元数据并刷新 <code>scrolls.json</code> 索引。</li>\n            <li><strong>提交 Pull Request</strong>：将修改推送到 GitHub 并向官方仓库发起 PR，审核合并后即可在所有服主的面板商店中显示！</li>\n        </ol>\n    </div>\n</div>\n"
            }
        ]
    },
    "en": {
        "sections": [
            {
                "id": "intro",
                "icon": "fa-rocket",
                "title": "卷轴系统理念与快速起步",
                "description": "轻量级、免侵入、全核心通用、绝对不崩服的控制台自动化系统",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    <strong>卷轴 (Scroll)</strong> 是 MC Web Panel 独创的免侵入自动化脚本系统。与传统的 Minecraft 服务端插件或模组（Bukkit/Spigot/Paper 插件、Forge/Fabric 模组）完全不同，卷轴运行在面板独立的 Node.js 事件循环与沙盒环境中，<strong>不需要在游戏服务端中安装任何前置 Mod 或 Loader</strong>。\n</p>\n\n<div class=\"row g-3 mb-4\">\n    <div class=\"col-md-4\">\n        <div class=\"card h-100 border-0 p-3 rounded-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n            <div class=\"d-flex align-items-center gap-2 mb-2 text-primary fw-bold\">\n                <i class=\"fa-solid fa-infinity\"></i>\n                <span>全核心全版本通用</span>\n            </div>\n            <p class=\"text-muted small mb-0 lh-base\">\n                纯净官方核心 (Vanilla)、Fabric、Forge、NeoForge、Paper、Purpur 乃至基岩版全版本兼容，彻底摆脱游戏大版本更新导致插件失效的困扰。\n            </p>\n        </div>\n    </div>\n    <div class=\"col-md-4\">\n        <div class=\"card h-100 border-0 p-3 rounded-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n            <div class=\"d-flex align-items-center gap-2 mb-2 text-success fw-bold\">\n                <i class=\"fa-solid fa-shield-halved\"></i>\n                <span>绝对隔离 · 永不崩服</span>\n            </div>\n            <p class=\"text-muted small mb-0 lh-base\">\n                卷轴代码运行在面板宿主进程中，即使脚本发生未捕获异常，也只会被沙盒安全隔离，绝不可能导致 Minecraft 服务端崩溃或损坏游戏存档。\n            </p>\n        </div>\n    </div>\n    <div class=\"col-md-4\">\n        <div class=\"card h-100 border-0 p-3 rounded-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n            <div class=\"d-flex align-items-center gap-2 mb-2 text-warning fw-bold\">\n                <i class=\"fa-solid fa-bolt\"></i>\n                <span>零停机 · 毫秒级热生效</span>\n            </div>\n            <p class=\"text-muted small mb-0 lh-base\">\n                支持在面板中在线修改代码或配置，保存后毫秒级热重载，无需重启服务器，随时随地敏捷调试与发布自动化交互规则。\n            </p>\n        </div>\n    </div>\n</div>\n\n<h5 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-folder-tree me-2 text-purple\"></i>极简目录结构</h5>\n<div class=\"row g-4 mb-4\">\n    <div class=\"col-md-6\">\n        <div class=\"code-block-wrapper shadow-sm rounded-4 overflow-hidden border\">\n            <div class=\"code-header d-flex justify-content-between px-3 py-2 small bg-dark bg-opacity-10 border-bottom\">\n                <span class=\"fw-bold\">目录树结构</span>\n                <span class=\"text-muted opacity-50\">Tree</span>\n            </div>\n            <pre class=\"p-3 small mb-0 dev-code-block\" style=\"background: var(--c-surface-elevated); overflow-x: auto; white-space: pre;\"><code>instances/<instanceId>/scrolls/my-scroll/\n├── scroll.json        # 卷轴清单元数据与配置规范 (必须)\n├── index.js           # 卷轴执行逻辑入口 (必须)\n└── config.json        # 卷轴个性化参数 (面板可视化配置)</code></pre>\n        </div>\n    </div>\n    <div class=\"col-md-6\">\n        <div class=\"code-block-wrapper shadow-sm rounded-4 overflow-hidden border\">\n            <div class=\"code-header d-flex justify-content-between px-3 py-2 small bg-dark bg-opacity-10 border-bottom\">\n                <span class=\"fw-bold\">快速起步模板</span>\n                <span class=\"text-muted opacity-50\">index.js</span>\n            </div>\n            <pre class=\"p-3 small mb-0 dev-code-block\" style=\"background: var(--c-surface-elevated); overflow-x: auto; white-space: pre;\"><code>module.exports = async function(scroll) {\n    // 监听玩家加入游戏\n    scroll.onPlayerJoin(async ({ player }) => {\n        scroll.sendTitle(player, {\n            title: \"欢迎进入世界\",\n            subtitle: \"享受精彩的冒险之旅！\",\n            color: \"gold\"\n        });\n        scroll.broadcast(\"§a欢迎玩家 §e\" + player + \" §a加入了服务器！\");\n    });\n\n    return {\n        destroy: async () => {\n            scroll.logger.info(\"卷轴注销清理完成\");\n        }\n    };\n};</code></pre>\n        </div>\n    </div>\n</div>\n"
            },
            {
                "id": "manifest",
                "icon": "fa-file-code",
                "title": "scroll.json 清单与可视化配置规范",
                "description": "元数据声明与 configSchema 动态配置表单生成机制",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    <code>scroll.json</code> 是卷轴的元数据清单文件，必须放置在卷轴的根目录下。系统不仅通过此文件识别卷轴名称与作者，还会依据 <code>configSchema</code> 自动在前端「卷轴工坊」中生成可视化的配置表单，让服主无需接触代码即可调整各项参数。\n</p>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-3 small text-uppercase text-secondary tracking-wider\">清单顶级字段说明</h6>\n        <div class=\"table-responsive\">\n            <table class=\"table table-sm dev-table mb-0 small text-muted\">\n                <thead>\n                    <tr class=\"border-bottom\">\n                        <th>字段名</th>\n                        <th>类型</th>\n                        <th>必填</th>\n                        <th>默认值</th>\n                        <th>说明</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr><td class=\"text-purple font-monospace py-2\">id</td><td>string</td><td class=\"text-danger\">是</td><td>—</td><td>卷轴唯一标识符，建议只包含小写字母、数字和中划线（如 <code>auto-cleaner</code>）。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">name</td><td>string | object</td><td class=\"text-danger\">是</td><td>—</td><td>显示名称。支持纯文本或中英多语言对象：<code>{ \"zh\": \"扫地姬\", \"en\": \"Auto Cleaner\" }</code>。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">version</td><td>string</td><td class=\"text-danger\">是</td><td>\"1.0.0\"</td><td>语义化版本号，如 <code>1.2.0</code>。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">author</td><td>string</td><td>否</td><td>—</td><td>作者或开发团队名称。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">description</td><td>string | object</td><td>否</td><td>—</td><td>功能介绍描述。支持纯文本或中英多语言对象。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">category</td><td>string</td><td>否</td><td>\"tools\"</td><td>分类归属，可选值：<code>tools</code>（系统工具）、<code>interactive</code>（玩家互动）、<code>utility</code>（实用辅助）。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">icon</td><td>string</td><td>否</td><td>\"fa-scroll\"</td><td>FontAwesome 6 图标类名（如 <code>fa-broom</code>, <code>fa-bed</code>, <code>fa-shield</code>）。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">color</td><td>string</td><td>否</td><td>\"#8b5cf6\"</td><td>卷轴在前端卡片的主题色 HEX 或 CSS 颜色值。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">main</td><td>string</td><td>否</td><td>\"index.js\"</td><td>执行逻辑入口文件相对路径。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">defaultEnabled</td><td>boolean</td><td>否</td><td>true</td><td>初次导入时是否默认启用。</td></tr>\n                    <tr><td class=\"text-purple font-monospace py-2\">configSchema</td><td>object | array</td><td>否</td><td>{}</td><td>可视化配置表单规范，详见下方。</td></tr>\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n\n<h5 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-sliders me-2 text-purple\"></i>configSchema 动态表单规格</h5>\n<p class=\"text-muted mb-3 small\">\n    支持对象字典定义或数组定义。系统支持四种基础控件类型：<code>string</code>（单行文本框）、<code>number</code>（数值微调框）、<code>boolean</code>（开关切换）、<code>select</code>（下拉选择框）。服主在面板保存的配置会即时注入到 <code>scroll.config</code> 中。\n</p>\n\n<div class=\"code-block-wrapper shadow-sm rounded-4 overflow-hidden border mb-4\">\n    <div class=\"code-header d-flex justify-content-between px-3 py-2 small bg-dark bg-opacity-10 border-bottom\">\n        <span class=\"fw-bold\">scroll.json 完整清单范例</span>\n        <span class=\"text-muted opacity-50\">JSON</span>\n    </div>\n    <pre class=\"p-3 small mb-0 dev-code-block\" style=\"background: var(--c-surface-elevated); overflow-x: auto; white-space: pre;\"><code>{\n    \"id\": \"welcome-scroll\",\n    \"name\": {\n        \"zh\": \"新手迎宾大标题\",\n        \"en\": \"Welcome Title\"\n    },\n    \"version\": \"1.0.0\",\n    \"author\": \"4YStudio\",\n    \"description\": {\n        \"zh\": \"玩家进入服务器时在屏幕中央展示金色 Title 大标题并发送欢迎广播。\",\n        \"en\": \"Shows a golden welcome title and broadcast message upon player join.\"\n    },\n    \"icon\": \"fa-bullhorn\",\n    \"color\": \"#f59e0b\",\n    \"category\": \"interactive\",\n    \"main\": \"index.js\",\n    \"defaultEnabled\": true,\n    \"configSchema\": {\n        \"welcomeMessage\": {\n            \"type\": \"string\",\n            \"title\": \"全服聊天欢迎词\",\n            \"default\": \"§a热烈欢迎新伙伴 §e{player} §a进入了服务器！\",\n            \"description\": \"支持 § 颜色代码，{player} 会自动替换为进服玩家名\"\n        },\n        \"titleText\": {\n            \"type\": \"string\",\n            \"title\": \"主标题文字\",\n            \"default\": \"欢迎光临\",\n            \"description\": \"全屏大标题主文本\"\n        },\n        \"titleColor\": {\n            \"type\": \"select\",\n            \"title\": \"主标题颜色\",\n            \"default\": \"gold\",\n            \"options\": [\n                { \"label\": \"金色 (Gold)\", \"value\": \"gold\" },\n                { \"label\": \"绿色 (Green)\", \"value\": \"green\" },\n                { \"label\": \"水青色 (Aqua)\", \"value\": \"aqua\" },\n                { \"label\": \"粉紫色 (Light Purple)\", \"value\": \"light_purple\" }\n            ]\n        },\n        \"countdownSec\": {\n            \"type\": \"number\",\n            \"title\": \"延时秒数\",\n            \"default\": 3,\n            \"min\": 1,\n            \"max\": 30\n        },\n        \"enableSound\": {\n            \"type\": \"boolean\",\n            \"title\": \"启用提示音效\",\n            \"default\": true\n        }\n    }\n}</code></pre>\n</div>\n"
            },
            {
                "id": "lifecycle",
                "icon": "fa-arrows-spin",
                "title": "生命周期与沙盒执行规范",
                "description": "模块导出契约、热重载流程与资源清理策略",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    卷轴的入口文件（默认为 <code>index.js</code>）必须导出一个 <code>async</code> 函数。当卷轴被加载或启用时，该函数会被调用，系统将向其注入唯一的 <strong>卷轴上下文对象 (scroll context)</strong>。\n</p>\n\n<div class=\"code-block-wrapper shadow-sm rounded-4 overflow-hidden border mb-4\">\n    <div class=\"code-header d-flex justify-content-between px-3 py-2 small bg-dark bg-opacity-10 border-bottom\">\n        <span class=\"fw-bold\">入口函数与销毁契约</span>\n        <span class=\"text-muted opacity-50\">Javascript</span>\n    </div>\n    <pre class=\"p-3 small mb-0 dev-code-block\" style=\"background: var(--c-surface-elevated); overflow-x: auto; white-space: pre;\"><code>/**\n * 卷轴入口函数\n * @param {Object} scroll - 卷轴上下文对象，注入全套 DSL 与环境接口\n */\nmodule.exports = async function(scroll) {\n    scroll.logger.info(\"卷轴正在初始化...\");\n\n    // 1. 初始化业务逻辑、注册监听器或定时任务\n    const timer = setInterval(() => {\n        // 自定义定时逻辑\n    }, 60000);\n\n    // 2. 返回包含 destroy 钩子的对象 (推荐)\n    return {\n        destroy: async () => {\n            clearInterval(timer); // 主动清理定时器\n            scroll.logger.info(\"卷轴已被注销并完成清理\");\n        }\n    };\n};</code></pre>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold text-warning mb-3\"><i class=\"fa-solid fa-triangle-exclamation me-2\"></i>定时器与资源防泄漏规范</h6>\n        <ul class=\"text-muted small mb-0 ps-3 lh-lg\">\n            <li><strong>优先使用 <code>scroll.schedule(intervalMs, fn)</code></strong>：引擎会在卷轴被禁用、重载或卸载时，<strong>全自动清理</strong>所有通过 <code>scroll.schedule</code> 注册的定时器，无需手动维护引用。</li>\n            <li><strong>原生 <code>setInterval</code> / <code>setTimeout</code></strong>：如果使用了 Node 原生定时器，必须在导出的 <code>destroy()</code> 钩子中执行 <code>clearInterval</code> / <code>clearTimeout</code>，避免重复产生幽灵定时任务。</li>\n            <li><strong>沙盒错误隔离</strong>：事件监听器内部的异常均被 <code>try-catch</code> 封装，即使你的代码出现运行时 TypeError，也不会导致面板崩溃或终止其他卷轴的执行。</li>\n        </ul>\n    </div>\n</div>\n"
            },
            {
                "id": "listeners",
                "icon": "fa-ear-listen",
                "title": "事件监听器 API 参考",
                "description": "监听玩家进出服、聊天指令拦截、阵亡与控制台日志",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    卷轴通过控制台数据流和原生事件驱动，无需任何侵入式客户端或服务端补丁即可捕获 Minecraft 服务器内部的关键事件：\n</p>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.onPlayerJoin(callback)</h6>\n        <p class=\"small text-muted mb-2\">当玩家加入游戏世界并完成握手连接时触发。</p>\n        <div class=\"table-responsive mb-3\">\n            <table class=\"table table-sm dev-table mb-0 small text-muted\">\n                <thead><tr class=\"border-bottom\"><th>参数属性</th><th>类型</th><th>说明</th></tr></thead>\n                <tbody>\n                    <tr><td class=\"font-monospace text-purple\">payload.player</td><td>string</td><td>加入服务器的玩家游戏 ID（如 <code>\"Alex\"</code>）。</td></tr>\n                    <tr><td class=\"font-monospace text-purple\">payload.raw</td><td>string</td><td>底层触发该事件的完整控制台原始日志行。</td></tr>\n                </tbody>\n            </table>\n        </div>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>scroll.onPlayerJoin(async ({ player }) => {\n    scroll.logger.info(\"玩家加入游戏: \" + player);\n    scroll.sendCommand(\"effect give \" + player + \" minecraft:speed 10 1 true\");\n});</code></pre>\n    </div>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.onPlayerQuit(callback)</h6>\n        <p class=\"small text-muted mb-2\">当玩家退出游戏世界或断开连接时触发。</p>\n        <div class=\"table-responsive mb-3\">\n            <table class=\"table table-sm dev-table mb-0 small text-muted\">\n                <thead><tr class=\"border-bottom\"><th>参数属性</th><th>类型</th><th>说明</th></tr></thead>\n                <tbody>\n                    <tr><td class=\"font-monospace text-purple\">payload.player</td><td>string</td><td>断开连接的玩家游戏 ID。</td></tr>\n                    <tr><td class=\"font-monospace text-purple\">payload.raw</td><td>string</td><td>控制台原始日志行。</td></tr>\n                </tbody>\n            </table>\n        </div>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>scroll.onPlayerQuit(async ({ player }) => {\n    scroll.broadcast(\"§7[提示] 玩家 \" + player + \" 悄悄离开了世界。\");\n});</code></pre>\n    </div>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.onChat(callback)</h6>\n        <p class=\"small text-muted mb-2\">捕获玩家在游戏公共聊天栏中的所有发言。<strong>是编写自定义控制台聊天指令（例如 <code>!spawn</code>、<code>!tpa</code>、<code>!help</code>）的核心利器！</strong></p>\n        <div class=\"table-responsive mb-3\">\n            <table class=\"table table-sm dev-table mb-0 small text-muted\">\n                <thead><tr class=\"border-bottom\"><th>参数属性</th><th>类型</th><th>说明</th></tr></thead>\n                <tbody>\n                    <tr><td class=\"font-monospace text-purple\">payload.player</td><td>string</td><td>发言玩家名称。</td></tr>\n                    <tr><td class=\"font-monospace text-purple\">payload.message</td><td>string</td><td>玩家发送的文本内容（已自动去除首尾空格）。</td></tr>\n                    <tr><td class=\"font-monospace text-purple\">payload.raw</td><td>string</td><td>控制台原始日志。</td></tr>\n                </tbody>\n            </table>\n        </div>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>scroll.onChat(async ({ player, message }) => {\n    // 监听聊天自定义指令\n    if (message === \"!spawn\" || message === \"！回城\") {\n        scroll.broadcast(\"§a[传送] 正在将玩家 §e\" + player + \" §a送回世界出生点...\");\n        scroll.sendCommand(\"tp \" + player + \" 0 80 0\");\n    }\n});</code></pre>\n    </div>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.onDeath(callback)</h6>\n        <p class=\"small text-muted mb-2\">捕获玩家阵亡事件及阵亡原因。</p>\n        <div class=\"table-responsive mb-3\">\n            <table class=\"table table-sm dev-table mb-0 small text-muted\">\n                <thead><tr class=\"border-bottom\"><th>参数属性</th><th>类型</th><th>说明</th></tr></thead>\n                <tbody>\n                    <tr><td class=\"font-monospace text-purple\">payload.player</td><td>string</td><td>阵亡玩家的 ID。</td></tr>\n                    <tr><td class=\"font-monospace text-purple\">payload.deathReason</td><td>string</td><td>阵亡讣告描述（如 <code>\"was slain by Zombie\"</code> 或 <code>\"fell from a high place\"</code>）。</td></tr>\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.onLog(callback)</h6>\n        <p class=\"small text-muted mb-2\">捕获服务端输出的每一行原始控制台文本。通过编写正则表达式，可以实现对任意 Mod 或插件输出的深度监听。</p>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>scroll.onLog(async ({ raw }) => {\n    // 捕获特定事件特征\n    if (raw.includes(\"Advancement Done\")) {\n        scroll.logger.info(\"玩家达成成就: \" + raw);\n    }\n});</code></pre>\n    </div>\n</div>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-2 text-purple font-monospace small\">scroll.schedule(intervalMs, callback)</h6>\n        <p class=\"small text-muted mb-2\">注册生命周期绑定的安全定时调度器。卷轴注销或禁用时，系统自动安全回收，防止内存泄漏。</p>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>// 每 10 分钟自动执行一次存档保存\nscroll.schedule(10 * 60 * 1000, async () => {\n    scroll.sendCommand(\"save-all\");\n    scroll.logger.info(\"自动执行 save-all 完成\");\n});</code></pre>\n    </div>\n</div>\n"
            },
            {
                "id": "dsl_api",
                "icon": "fa-wand-magic-sparkles",
                "title": "DSL 上下文工具 API 参考",
                "description": "操作指令注入、全屏大标题、ActionBar、数据存取全套函数",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    系统向卷轴入口函数注入的 <code>scroll</code> 对象封装了一系列高抽象度、开箱即用的实用 DSL 工具：\n</p>\n\n<div class=\"table-responsive mb-4\">\n    <table class=\"table table-sm dev-table mb-0 small text-muted\">\n        <thead>\n            <tr class=\"border-bottom\">\n                <th>方法 / 属性</th>\n                <th>签名 / 类型</th>\n                <th>说明</th>\n            </tr>\n        </thead>\n        <tbody>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.sendCommand(cmd)</td>\n                <td><code>(cmd: string) => void</code></td>\n                <td>向当前活跃 Minecraft 服务器的控制台标准输入 (stdin) 发送命令。无需加斜杠前缀 <code>/</code>。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.sendTitle(player, opts)</td>\n                <td><code>(player: string, opts: Object) => void</code></td>\n                <td>向指定玩家（或 <code>@a</code> 全体玩家）屏幕正中央发送标题。支持 <code>title</code>、<code>subtitle</code>、<code>color</code>、<code>fadeIn</code>、<code>stay</code>、<code>fadeOut</code>。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.sendActionBar(player, text)</td>\n                <td><code>(player: string, text: string) => void</code></td>\n                <td>向指定玩家发送屏幕底部快捷栏通知（ActionBar），不遮挡视野，支持颜色代码。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.broadcast(text)</td>\n                <td><code>(text: string) => void</code></td>\n                <td>向全服聊天框广播一条格式化消息。内置安全转义，支持 <code>§</code> 颜色代码。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.storage</td>\n                <td><code>ScrollStorage</code></td>\n                <td>内置持久化键值对存储数据库，数据安全保存至本地 <code>data/storage.json</code>。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.config</td>\n                <td><code>Object</code></td>\n                <td>只读对象。实时包含服主在前端界面为该卷轴配置的键值参数。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.logger</td>\n                <td><code>{ info, warn, error }</code></td>\n                <td>标准化日志记录器，输出自动带有 <code>[Scroll:ID]</code> 前缀。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.sleep(ms)</td>\n                <td><code>(ms: number) => Promise&lt;void&gt;</code></td>\n                <td>异步休眠等待工具函数，用法：<code>await scroll.sleep(1000)</code>。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.instancesDir</td>\n                <td><code>string</code></td>\n                <td>服务器实例存储根目录的绝对物理路径。</td>\n            </tr>\n            <tr>\n                <td class=\"text-purple font-monospace py-2\">scroll.instanceId</td>\n                <td><code>string</code></td>\n                <td>当前所绑定的实例 ID（如 <code>default</code>）。</td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n\n<h5 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-database me-2 text-purple\"></i>scroll.storage 持久化存储详解</h5>\n<div class=\"code-block-wrapper shadow-sm rounded-4 overflow-hidden border mb-4\">\n    <div class=\"code-header d-flex justify-content-between px-3 py-2 small bg-dark bg-opacity-10 border-bottom\">\n        <span class=\"fw-bold\">Storage 使用范例</span>\n        <span class=\"text-muted opacity-50\">Javascript</span>\n    </div>\n    <pre class=\"p-3 small mb-0 dev-code-block\" style=\"background: var(--c-surface-elevated); overflow-x: auto; white-space: pre;\"><code>// 读取键值（提供默认值）\nconst points = scroll.storage.get(\"player_points_\" + player, 0);\n\n// 设置键值（自动写入 data/storage.json）\nscroll.storage.set(\"player_points_\" + player, points + 10);\n\n// 判断是否存在某键\nif (scroll.storage.has(\"last_checkin_time\")) { ... }\n\n// 删除键\nscroll.storage.delete(\"temp_token\");\n\n// 获取全部键值对象\nconst allData = scroll.storage.getAll();</code></pre>\n</div>\n"
            },
            {
                "id": "minecraft_commands",
                "icon": "fa-terminal",
                "title": "Minecraft 原版指令与 Tellraw/Title 格式指南",
                "description": "色彩代码、JSON Text 规范与跨版本兼容技巧",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    在编写卷轴交互时，合理使用原版 <code>/tellraw</code> 和 <code>/title</code> 命令可以呈现极其绚丽的 UI 效果：\n</p>\n\n<div class=\"row g-4 mb-4\">\n    <div class=\"col-md-6\">\n        <div class=\"card h-100 border-0 p-3 rounded-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n            <h6 class=\"fw-bold text-primary mb-3\">经典 § 颜色代码对照</h6>\n            <div class=\"row g-2 small font-monospace\">\n                <div class=\"col-6\"><span style=\"color:#000000;background:#fff;padding:2px 4px;border-radius:4px;\">§0 黑色</span></div>\n                <div class=\"col-6\"><span style=\"color:#0000aa;\">§1 深蓝</span></div>\n                <div class=\"col-6\"><span style=\"color:#00aa00;\">§2 深绿</span></div>\n                <div class=\"col-6\"><span style=\"color:#00aaaa;\">§3 湖蓝</span></div>\n                <div class=\"col-6\"><span style=\"color:#aa0000;\">§4 深红</span></div>\n                <div class=\"col-6\"><span style=\"color:#aa00aa;\">§5 紫色</span></div>\n                <div class=\"col-6\"><span style=\"color:#ffaa00;\">§6 金黄</span></div>\n                <div class=\"col-6\"><span style=\"color:#aaaaaa;\">§7 灰色</span></div>\n                <div class=\"col-6\"><span style=\"color:#555555;\">§8 深灰</span></div>\n                <div class=\"col-6\"><span style=\"color:#5555ff;\">§9 亮蓝</span></div>\n                <div class=\"col-6\"><span style=\"color:#55ff55;\">§a 亮绿</span></div>\n                <div class=\"col-6\"><span style=\"color:#55ffff;\">§b 天蓝</span></div>\n                <div class=\"col-6\"><span style=\"color:#ff5555;\">§c 鲜红</span></div>\n                <div class=\"col-6\"><span style=\"color:#ff55ff;\">§d 粉红</span></div>\n                <div class=\"col-6\"><span style=\"color:#ffff55;\">§e 黄色</span></div>\n                <div class=\"col-6\"><span style=\"color:#ffffff;\">§f 白色</span></div>\n            </div>\n        </div>\n    </div>\n    <div class=\"col-md-6\">\n        <div class=\"card h-100 border-0 p-3 rounded-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n            <h6 class=\"fw-bold text-success mb-3\">Minecraft 原版 JSON Text 规范</h6>\n            <p class=\"small text-muted mb-2\">使用 <code>/tellraw</code> 或 <code>/title</code> 时，文本对象遵循标准 JSON 格式：</p>\n            <pre class=\"p-2 small mb-0 rounded-3 border\" style=\"background: var(--c-surface); font-size: 0.75rem;\"><code>[\"\", {\"text\":\"[公告] \",\"color\":\"gold\",\"bold\":true}, {\"text\":\"欢迎访问官网！\",\"color\":\"yellow\",\"clickEvent\":{\"action\":\"open_url\",\"value\":\"https://example.com\"}}]</code></pre>\n        </div>\n    </div>\n</div>\n"
            },
            {
                "id": "examples",
                "icon": "fa-laptop-code",
                "title": "五大实战案例全套代码",
                "description": "从聊天回城指令到单人跳过黑夜，开箱即用的完整实战源码",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    以下提供了 5 个高频实用场景的完整卷轴代码，可直接复制到面板「在线工坊」或本地目录中使用：\n</p>\n\n<!-- 案例 1 -->\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <div class=\"d-flex align-items-center gap-2 mb-2\">\n            <span class=\"badge bg-primary rounded-pill px-2.5\">案例 1</span>\n            <h6 class=\"fw-bold m-0\">聊天快捷指令回城卷轴 (!spawn)</h6>\n        </div>\n        <p class=\"small text-muted mb-3\">玩家在聊天框输入 <code>!spawn</code>，卷轴检查 60 秒冷却时间，若冷却完毕则将其传送至世界出生点并扣除传送费用。</p>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>module.exports = async function(scroll) {\n    const cooldowns = new Map();\n\n    scroll.onChat(async ({ player, message }) => {\n        if (message.trim().toLowerCase() !== \"!spawn\" && message.trim() !== \"！回城\") return;\n\n        const now = Date.now();\n        const lastUsed = cooldowns.get(player) || 0;\n        const remaining = Math.ceil((60000 - (now - lastUsed)) / 1000);\n\n        if (remaining > 0) {\n            scroll.sendActionBar(player, \"§c冷却中！还需等待 \" + remaining + \" 秒后方可再次回城。\");\n            return;\n        }\n\n        cooldowns.set(player, now);\n        scroll.sendActionBar(player, \"§a正在传送回世界出生点...\");\n        scroll.sendCommand(\"tp \" + player + \" 0 80 0\");\n        scroll.sendCommand(\"effect give \" + player + \" minecraft:regeneration 5 1 true\");\n        scroll.broadcast(\"§6[传送] §e玩家 §b\" + player + \" §e已安全传送回城。\");\n    });\n\n    return {\n        destroy: async () => {\n            cooldowns.clear();\n        }\n    };\n};</code></pre>\n    </div>\n</div>\n\n<!-- 案例 2 -->\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <div class=\"d-flex align-items-center gap-2 mb-2\">\n            <span class=\"badge bg-success rounded-pill px-2.5\">案例 2</span>\n            <h6 class=\"fw-bold m-0\">违禁词自动检测与警告卷轴</h6>\n        </div>\n        <p class=\"small text-muted mb-3\">检测玩家聊天内容，包含敏感词时自动拦截并记录警告次数，达到 3 次自动执行临时禁言或踢出。</p>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>module.exports = async function(scroll) {\n    const BAD_WORDS = [\"炸服\", \"外挂\", \"刷物品\", \"骂人词\"];\n\n    scroll.onChat(async ({ player, message }) => {\n        const found = BAD_WORDS.some(word => message.includes(word));\n        if (!found) return;\n\n        const count = (scroll.storage.get(\"warn_\" + player, 0)) + 1;\n        scroll.storage.set(\"warn_\" + player, count);\n\n        scroll.broadcast(\"§c[巡查姬] §e玩家 §b\" + player + \" §e发表了违规言论！(累计警告: \" + count + \"/3)\");\n        scroll.sendTitle(player, {\n            title: \"§c言论违规警告\",\n            subtitle: \"请文明游戏，当前警告: \" + count + \"/3\",\n            color: \"red\"\n        });\n\n        if (count >= 3) {\n            scroll.sendCommand(\"kick \" + player + \" 您因多次违规发言已被移出服务器\");\n            scroll.storage.set(\"warn_\" + player, 0);\n        }\n    });\n};</code></pre>\n    </div>\n</div>\n\n<!-- 案例 3 -->\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <div class=\"d-flex align-items-center gap-2 mb-2\">\n            <span class=\"badge bg-warning text-dark rounded-pill px-2.5\">案例 3</span>\n            <h6 class=\"fw-bold m-0\">定时全服整点红包/幸运抽奖卷轴</h6>\n        </div>\n        <p class=\"small text-muted mb-3\">每隔 1 小时向全服在线玩家派发随机经验或物品奖励，活跃服务器气氛。</p>\n        <pre class=\"p-3 small mb-0 dev-code-block rounded-3 border\" style=\"background: var(--c-surface);\"><code>module.exports = async function(scroll) {\n    // 每 60 分钟执行一次\n    scroll.schedule(60 * 60 * 1000, async () => {\n        scroll.broadcast(\"§d[幸运天降] §e整点空投已抵达！全体在线玩家获得 5 级经验与金苹果奖励！\");\n        scroll.sendCommand(\"xp add @a 5 levels\");\n        scroll.sendCommand(\"give @a minecraft:golden_apple 1\");\n        scroll.sendCommand(\"playsound minecraft:ui.toast.challenge_complete master @a\");\n    });\n};</code></pre>\n    </div>\n</div>\n"
            },
            {
                "id": "publishing",
                "icon": "fa-cloud-arrow-up",
                "title": "打包与发布至 GitHub 卷轴商店",
                "description": "如何将自制卷轴打包并提交到官方在线商店",
                "content": "\n<p class=\"text-muted mb-4 lh-lg\">\n    编写完成并自测通过的卷轴，可以非常方便地打包并提交给云语官方仓库，让全球的服主在面板中一键下载安装：\n</p>\n\n<div class=\"card border-0 shadow-sm rounded-4 mb-4\" style=\"background: var(--c-surface-elevated); border: 1px solid var(--c-border) !important;\">\n    <div class=\"card-body p-4\">\n        <h6 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-file-zipper me-2 text-purple\"></i>打包规范说明</h6>\n        <ol class=\"small text-muted ps-3 mb-0 lh-lg\">\n            <li><strong>根目录结构</strong>：进入你的卷轴目录，将 <code>scroll.json</code> 和 <code>index.js</code> 直接选中并打包为 ZIP 文件（注意：不要在 ZIP 内包含多余的一层同名文件夹）。</li>\n            <li><strong>文件名规范</strong>：ZIP 文件名必须严格与 <code>scroll.json</code> 中的 <code>id</code> 保持一致，例如 <code>my-scroll.zip</code>。</li>\n            <li><strong>自动构建索引</strong>：将打包好的 <code>my-scroll.zip</code> 放置于项目的 <code>docs/scrolls_shop/</code> 目录下，运行 <code>npm run build:scrolls-shop</code>，系统会自动解析元数据并刷新 <code>scrolls.json</code> 索引。</li>\n            <li><strong>提交 Pull Request</strong>：将修改推送到 GitHub 并向官方仓库发起 PR，审核合并后即可在所有服主的面板商店中显示！</li>\n        </ol>\n    </div>\n</div>\n"
            }
        ]
    }
};
